public class SorterCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(Sorter impl) {
        try {
            return SorterChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectSorter()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectSorter()));
        check("rejects the mutates-the-callers-array bug", false, verdict(new MutatingSorter()));
        check("rejects the only-right-on-sorted-input bug", false, verdict(new SinglePassSorter()));
        check("rejects the crash-on-one-element bug", false, verdict(new CrashOnSingletonSorter()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectSorter implements Sorter {
    public int[] sortedCopy(int[] values) {
        int[] copy = values.clone();
        java.util.Arrays.sort(copy);
        return copy;
    }
}

class AlsoCorrectSorter implements Sorter {
    public int[] sortedCopy(int[] values) {
        int[] copy = java.util.Arrays.copyOf(values, values.length);
        for (int i = 1; i < copy.length; i++) {
            int current = copy[i];
            int j = i - 1;
            while (j >= 0 && copy[j] > current) {
                copy[j + 1] = copy[j];
                j--;
            }
            copy[j + 1] = current;
        }
        return copy;
    }
}

class MutatingSorter implements Sorter {
    public int[] sortedCopy(int[] values) {
        java.util.Arrays.sort(values);
        return values;
    }
}

class SinglePassSorter implements Sorter {
    public int[] sortedCopy(int[] values) {
        int[] copy = values.clone();
        for (int i = 0; i < copy.length - 1; i++) {
            if (copy[i] > copy[i + 1]) {
                int swap = copy[i];
                copy[i] = copy[i + 1];
                copy[i + 1] = swap;
            }
        }
        return copy;
    }
}

class CrashOnSingletonSorter implements Sorter {
    public int[] sortedCopy(int[] values) {
        if (values.length == 0) return new int[0];
        if (values.length == 1) return new int[] {values[1]};
        int[] copy = values.clone();
        java.util.Arrays.sort(copy);
        return copy;
    }
}

