/**
 * TASK: Write the checks that decide whether a Sorter is correct.
 *
 * The Sorter contract:
 *   sortedCopy(values) returns a NEW array holding the same numbers in
 *       ascending order. Duplicates are kept.
 *   The array passed in must come back UNTOUCHED -- sortedCopy has no side
 *       effects on its argument.
 *   sortedCopy of an empty array returns an empty array; of a one-element
 *       array, a one-element copy.
 *   Examples: sortedCopy({5, 3, 1, 4}) -> {1, 3, 4, 5},
 *             sortedCopy({2, 2, 1}) -> {1, 2, 2}, sortedCopy({7}) -> {7}
 *
 * Two of these bugs are invisible if you only look at the returned array. One
 * implementation sorts the caller's array in place, so you must remember what
 * you passed in and inspect it AFTER the call. Another only looks right when
 * the input was already sorted. A third throws on a one-element array, so wrap
 * your calls in try/catch and return false if anything is thrown.
 *
 * Compare arrays with java.util.Arrays.toString(...) or Arrays.equals(...).
 */
interface Sorter {
    /* Provided -- do not edit. */
    int[] sortedCopy(int[] values);
}

public class SorterChecker {

    public static boolean isCorrect(Sorter impl) {
        try {
            int[] jumbled = {5, 3, 1, 4};
            if (!same(impl.sortedCopy(jumbled), new int[] {1, 3, 4, 5})) return false;
            // The caller's array must be exactly as it was handed over.
            if (!same(jumbled, new int[] {5, 3, 1, 4})) return false;

            int[] duplicates = {2, 2, 1};
            if (!same(impl.sortedCopy(duplicates), new int[] {1, 2, 2})) return false;
            if (!same(duplicates, new int[] {2, 2, 1})) return false;

            if (!same(impl.sortedCopy(new int[] {1, 2, 3}), new int[] {1, 2, 3})) return false;
            if (!same(impl.sortedCopy(new int[] {7}), new int[] {7})) return false;
            if (!same(impl.sortedCopy(new int[] {}), new int[] {})) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }

    private static boolean same(int[] actual, int[] expected) {
        return actual != null && java.util.Arrays.equals(actual, expected);
    }
}
